    public static function connection(App $a,string $site,string $kind):array {$v=$a->store->get('external_connections',$site.':'.$kind);if(!$v)Http::error(409,'connector_missing');$v['secret']=Security::unseal($v['encrypted'],$a->config);return $v;}
    public static function range(array $b,int $max=366):array {foreach(['start','end'] as $k)if(!is_string($b[$k]??null)||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$b[$k])||gmdate('Y-m-d',strtotime($b[$k]))!==$b[$k])Http::error(400,'aggregate_range_invalid');$days=(strtotime($b['end'])-strtotime($b['start']))/86400+1;if($days<1||$days>$max)Http::error(400,'aggregate_range_invalid');return ['start'=>$b['start'],'end'=>$b['end']];}
