    private static function automaticSuggestions(App $a,string $site,array $result):array
    {
        $e=$result['evidence'];$candidates=[];$add=static function($title,$category,$affected,$severity,$metric)use(&$candidates){$candidates[]=['title'=>mb_substr($title,0,1000),'category'=>$category,'priority_score'=>max(0,$affected*$severity),'priority_basis'=>['method'=>'affected-count-times-observed-severity','affectedCount'=>$affected,'observedSeverity'=>$severity,'metric'=>$metric,'caveat'=>'观测数量与严重程度的优先级代理，不是实测收益或因果结论']];};
