        foreach($e['seo']['pages']??[] as $page)if($page['issues']??[])$add('复核 '.$page['url'].'：'.implode('、',$page['issues']),'seo',1,count($page['issues']),'SEO已观察问题');
        if(!$candidates)$add('证据不足：请补充流量与转化目标，再评估整改优先级','analysis',0,0,'缺少有效样本');usort($candidates,fn($x,$y)=>$y['priority_score']<=>$x['priority_score']);return $a->db->transaction(function()use($a,$site,$result,$candidates){$a->db->lock('site:'.$site);if(($result['evidence']['aggregation']['epoch']??null)!==self::epoch($a,$site))Http::error(409,'evidence_missing');$ids=[];foreach(array_slice($candidates,0,20) as $candidate){$id=substr(hash('sha256',$result['id'].':'.$candidate['title']),0,32);$v=$candidate+['id'=>$id,'site_id'=>$site,'evidence_id'=>$result['id'],'confidence'=>'low','status'=>'new','created_at'=>Store::now()];$a->store->put('ai_suggestions',$id,$v,$site);$ids[]=$id;}return $ids;});
    }
