    private static function googleToken(App $a,string $s):array {$c=self::connection($a,$s,'google');$secret=json_decode($c['secret'],true,32,JSON_THROW_ON_ERROR);if(!($secret['refreshToken']??null))Http::error(409,'google_authorization_required');$v=self::json('https://oauth2.googleapis.com/token',['method'=>'POST','headers'=>['Content-Type'=>'application/x-www-form-urlencoded'],'body'=>http_build_query(['client_id'=>$c['settings']['clientId'],'client_secret'=>$secret['clientSecret'],'refresh_token'=>$secret['refreshToken'],'grant_type'=>'refresh_token'])]);if(!is_string($v['access_token']??null))Http::error(502,'external_response_invalid');return [$c,$v['access_token']];}
