    }
    public static function tick(App $a):array
    {
        $expired=0;foreach($a->store->list('sites') as $site)$a->db->transaction(function()use($a,$site){$a->db->lock('site:'.$site['id']);Governance::ensureApplied($a,$site['id']);});foreach($a->store->list('ai_reservations') as $r)if($r['status']==='reserved'&&strtotime($r['expires_at'])<=time()){self::settle($a,$r['site_id'],$r['id'],null,'expired',['answer'=>null]);$expired++;}
        foreach($a->store->list('external_connections') as $c){$settings=$c['settings'];$s=$c['site_id'];$site=$a->store->get('sites',$s);if(!$site)continue;$zone=new \DateTimeZone($site['timezone']??'UTC');$localNow=new \DateTimeImmutable('now',$zone);$day=$localNow->format('Y-m-d');$yesterday=$localNow->modify('-1 day')->format('Y-m-d');$prior=$localNow->modify('-2 days')->format('Y-m-d');if($c['kind']==='google'){if($settings['dailyGsc']??false)self::scheduleExternal($a,$s,'gsc',['start'=>gmdate('Y-m-d',time()-9*86400),'end'=>gmdate('Y-m-d',time()-3*86400)],$day);if($settings['dailyGa4']??false)self::scheduleExternal($a,$s,'ga4',['start'=>$yesterday,'end'=>$yesterday],$day);}elseif(in_array($c['kind'],['serpapi','dataforseo'],true)&&($settings['daily']??false))foreach($settings['keywords']??[] as $keyword)self::scheduleExternal($a,$s,'serp',['keyword'=>$keyword,'provider'=>$c['kind']],$day.':'.$keyword);elseif($c['kind']==='ai'&&($settings['enabled']??false)){if($settings['dailyReport']??false)self::scheduleExternal($a,$s,'ai',['start'=>$yesterday,'end'=>$yesterday,'purpose'=>'daily'],$day.':daily');if($settings['automaticAnomaly']??false){$now=self::stats($a,$s,['start'=>$yesterday,'end'=>$yesterday]);$before=self::stats($a,$s,['start'=>$prior,'end'=>$prior]);$baseline=$before['totals']['pv']??0;if($baseline>=20&&abs(($now['totals']['pv']??0)-$baseline)/$baseline>=0.5)self::scheduleExternal($a,$s,'ai',['start'=>$yesterday,'end'=>$yesterday,'purpose'=>'anomaly'],$day.':anomaly');}}}
        foreach($a->store->list('sites') as $site)if($site['config']['seoAutoScan']??false)self::scheduleExternal($a,$site['id'],'seo',[],gmdate('Y-m-d'));return ['expired_reservations'=>$expired];
    }
    private static function scheduleExternal(App $a,string $s,string $type,array $payload,string $key):void
    {
        $id=hash('sha256',$s.$type.$key);$a->db->transaction(function()use($a,$s,$type,$payload,$key,$id){$a->db->lock('site:'.$s);if($a->store->get('external_scheduled',$id))return;$site=$a->store->get('sites',$s);$day=EventPrivacy::day(Store::now(),$site['timezone']??'UTC');$payload['_jobKey']=strlen($key)>200?hash('sha256',$key):$key;$payload['_day']=$day;$queue=Queue::enqueue($a,'external:'.$type,$s,$payload,'external:'.$id);$a->store->put('external_scheduled',$id,['id'=>$id,'site_id'=>$s,'queue_id'=>$queue,'created_at'=>Store::now()],$s);});
    }
    public static function work(App $a,array $job):array
    {
        $s=$job['site_id'];$p=$job['payload'];$valid=$a->db->transaction(function()use($a,$s,$job){$a->db->lock('site:'.$s);Governance::ensureApplied($a,$s);$current=$a->store->get('queue_jobs',$job['id']);return $current&&($current['status']??'')==='running'&&is_string($current['lease_token']??null)&&hash_equals($current['lease_token'],(string)($job['lease_token']??''))&&isset($current['lease_until'])&&EventPrivacy::millis($current['lease_until'])>microtime(true)*1000;});if(!$valid)Http::error(409,'external_job_cancelled');$result=match($job['type']){'external:gsc'=>self::importGSC($a,$s,$p),'external:ga4'=>self::importGA4($a,$s,$p),'external:serp'=>self::rank($a,$s,$p['keyword'],$p['provider']),'external:seo'=>self::seoScan($a,$s),'external:ai'=>self::invokeAI($a,$s,$p['purpose']??'daily','解读聚合指标并说明证据与不确定性',$p,$job['id'].':'.($job['revision']??1)),default=>throw new \RuntimeException('unsupported_external_job')};if($job['type']==='external:ai'&&($result['status']??'')!=='complete')throw new \RuntimeException('ai_attempt_already_settled');return $result;
    }
    public static function jobs(App $a,string $site):array
    {
        $rows=[];foreach($a->store->list('queue_jobs',$site) as $job){if(!str_starts_with((string)($job['type']??''),'external:'))continue;$kind=substr($job['type'],9);if($kind==='ai')$kind='ai-'.($job['payload']['purpose']??'daily');$status=$job['status'];if($status==='dead'||($status==='pending'&&$job['attempts']>0))$status='failed';$rows[]=['id'=>$job['id'],'site_id'=>$site,'kind'=>$kind,'job_key'=>$job['payload']['_jobKey']??$job['id'],'day'=>$job['payload']['_day']??substr($job['created_at'],0,10),'status'=>$status,'attempts'=>$job['attempts'],'max_attempts'=>8,'next_attempt_at'=>$job['available_at'],'started_at'=>$job['updated_at'],'finished_at'=>$job['completed_at']??null,'lease_until'=>$job['lease_until'],'error'=>$job['error']??null,'engine'=>'mysql-queue','retrySemantics'=>'AI automatic retries reuse the same paid-attempt ledger; an explicit retry creates a new request revision'];}usort($rows,fn($x,$y)=>strcmp($y['day'].$y['started_at'],$x['day'].$x['started_at']));return array_slice($rows,0,100);
    }
