        $r->add('GET','/api/google/callback',function(Http $h)use($a){$u=$a->auth->user($h);$id=Security::hashToken((string)($h->query['state']??''));$state=$a->db->transaction(function()use($a,$h,$u,$id){$a->db->lock('oauth:'.$id);$v=$a->store->get('oauth_states',$id);if(!$v||$v['user_id']!==$u['id']||!hash_equals($v['session_hash'],Security::hashToken($h->cookie('baize_session')??''))||strtotime($v['expires_at'])<=time())Http::error(403,'oauth_state_invalid');$a->store->delete('oauth_states',$id);return $v;});$s=$state['site_id'];$a->auth->authorize($h,$s,'admin');$c=self::connection($a,$s,'google');if($c['revision']!==$state['revision'])Http::error(409,'external_config_changed');$secret=json_decode($c['secret'],true,32,JSON_THROW_ON_ERROR);$tokens=self::json('https://oauth2.googleapis.com/token',['method'=>'POST','headers'=>['Content-Type'=>'application/x-www-form-urlencoded'],'body'=>http_build_query(['code'=>Governance::text($h->query['code']??null,2000),'client_id'=>$c['settings']['clientId'],'client_secret'=>$secret['clientSecret'],'redirect_uri'=>$c['settings']['redirectUri'],'grant_type'=>'authorization_code','code_verifier'=>Security::unseal($state['verifier'],$a->config)])]);$secret['refreshToken']=$tokens['refresh_token']??$secret['refreshToken']??null;if(!$secret['refreshToken'])Http::error(409,'google_authorization_required');$a->db->transaction(function()use($a,$s,$c,$secret){$a->db->lock('site:'.$s);$now=$a->store->get('external_connections',$c['id']);if(!$now||$now['revision']!==$c['revision'])Http::error(409,'external_config_changed');unset($c['secret']);$c['encrypted']=Security::seal(Operations::json($secret),$a->config);$c['revision']=Store::uuid();$a->store->put('external_connections',$c['id'],$c,$s);});return ['connected'=>true];});
    }
