        $r->add('GET',$base.'/suggestions',function(Http $h)use($a){$s=$h->params['siteId'];$a->auth->authorize($h,$s);$rows=[];$epoch=self::epoch($a,$s);foreach($a->store->list('ai_suggestions',$s) as $v){$e=$a->store->get('ai_calls',$v['evidence_id']);if($e&&($e['evidence']['aggregation']['epoch']??null)===$epoch)$rows[]=array_merge($v,['evidence'=>$e['evidence']]);}return ['rows'=>$rows];});
        $r->add('PATCH',$base.'/suggestions/:id',function(Http $h)use($a){$s=$h->params['siteId'];$a->auth->authorize($h,$s,'write');return $a->db->transaction(function()use($a,$h,$s){$a->db->lock('site:'.$s);$v=$a->store->get('ai_suggestions',$h->params['id']);$next=$h->body['status']??'';$transitions=['new'=>['in-progress','dismissed'],'in-progress'=>['new','pending-recheck','dismissed'],'pending-recheck'=>['in-progress','verified','dismissed'],'verified'=>['in-progress'],'dismissed'=>['new']];if(!$v||$v['site_id']!==$s||!in_array($next,$transitions[$v['status']]??[],true)||($next==='pending-recheck'&&!isset($h->body['implementedAt']))||($next==='verified'&&!isset($v['recheck'])))Http::error(400,'suggestion_transition_invalid');if($next==='verified'&&$v['category']==='seo'){ $findings=$v['recheck']['seoRecheck']['findingResults']??[];if(!$findings||array_filter($findings,fn($f)=>($f['status']??'')!=='fixed'))Http::error(400,'suggestion_transition_invalid');}$v['status']=$next;if(isset($h->body['implementedAt']))$v['implemented_at']=$h->body['implementedAt'];if(in_array($next,['new','in-progress'],true))unset($v['recheck']);$a->store->put('ai_suggestions',$v['id'],$v,$s);return ['updated'=>true];});});
        $r->add('POST',$base.'/suggestions/:id/recheck',function(Http $h)use($a){$s=$h->params['siteId'];$a->auth->authorize($h,$s,'write');$v=$a->store->get('ai_suggestions',$h->params['id']);if(!$v||$v['site_id']!==$s||$v['status']!=='pending-recheck'||!is_array($h->body['confounders']??null)||!$h->body['confounders'])Http::error(400,'suggestion_transition_invalid');$old=$a->store->get('ai_calls',$v['evidence_id']);if(!$old)Http::error(409,'evidence_missing');$after=self::evidence($a,$s,self::range($h->body,31));$comparison=['before'=>$old['evidence'],'after'=>$after,'confounders'=>array_slice($h->body['confounders'],0,20),'conclusion'=>'观察性对照，流量、季节性和同期改动可能解释变化，不能证明因果','checkedAt'=>Store::now()];if($v['category']==='seo'){$a->auth->authorize($h,$s,'admin');$beforeScanId=$old['evidence']['seo']['scanId']??null;if(!$beforeScanId)Http::error(409,'evidence_missing');$comparison['seoRecheck']=ProviderReports::seoRecheck($a,$s,$beforeScanId);}$v['recheck']=$comparison;Governance::write($a,$s,'ai_suggestions',$v);return $comparison;});
    }
